package com.collabspace.controller; import com.collabspace.entity.*;import com.collabspace.repository.*;import com.collabspace.service.CurrentUserService;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.util.*; @RestController @RequestMapping("/api/conversations") @RequiredArgsConstructor public class ConversationController {private final DirectConversationRepository repo;private final CurrentUserService current; @GetMapping public List<Map<String,Object>> list(){UUID id=current.get().getId();return repo.findByUserOneIdOrUserTwoId(id,id).stream().map(c->{User other=c.getUserOne().getId().equals(id)?c.getUserTwo():c.getUserOne();return Map.<String,Object>of("id",c.getId(),"userId",other.getId(),"username",other.getUsername(),"email",other.getEmail(),"status",other.getStatus().name());}).toList();}}